import os

MODE = os.environ["WF_MUTANT"]
HIT = os.environ["WF_MUTANT_HIT"]


def _hit():
    with open(HIT, "a") as f:
        f.write(MODE + "\n")


class _NoLock:
    def acquire(self, blocking=True, timeout=-1):
        return True

    def release(self):
        pass

    def locked(self):
        return False

    def __enter__(self):
        return True

    def __exit__(self, *exc):
        return False


def pytest_sessionstart(session):
    if MODE == "lock":
        from wantrain.runtime.stage import StageRuntime

        lock = _NoLock()

        def get(self):
            _hit()
            return lock

        StageRuntime._tel_lock = property(get, lambda self, value: None)
    elif MODE in ("launch-zero", "launch-late"):
        from wantrain.coordinator.coordinator import Coordinator

        orig = Coordinator._restore_and_relaunch

        def relaunch(self, run, step, *args, **kwargs):
            out = orig(self, run, step, *args, **kwargs)
            if step is not None:
                for st in list(run.states.values()):
                    st.start_step = 0 if MODE == "launch-zero" else st.start_step + 2
                    _hit()
            return out

        Coordinator._restore_and_relaunch = relaunch
    elif MODE == "identity":
        from wantrain.coordinator.coordinator import Coordinator

        orig = Coordinator._slot_for

        def slot_for(self, w, msg):
            run, slot = orig(self, w, msg)
            if run is not None and isinstance(msg, dict) and msg.get("kind") == "TELEMETRY":
                named = (msg.get("rank"), msg.get("peer"))
                if named in run.slots and named != slot:
                    _hit()
                    return run, named
            return run, slot

        Coordinator._slot_for = slot_for
    elif MODE == "identity-telem":
        from wantrain.coordinator.coordinator import Coordinator

        orig = Coordinator._slot_for

        def slot_for(self, w, msg):
            run, slot = orig(self, w, msg)
            summary = msg.get("summary") if isinstance(msg, dict) and msg.get("kind") == "TELEM_STEP" else None
            if run is not None and isinstance(summary, dict):
                named = (summary.get("rank"), summary.get("peer"))
                if all(type(x) is int for x in named) and named in run.slots and named != slot:
                    _hit()
                    return run, named
            return run, slot

        Coordinator._slot_for = slot_for
    elif MODE == "metric-src":
        from wantrain.coordinator.coordinator import Coordinator

        orig = Coordinator._dispatch

        def dispatch(self, w, msg, body):
            if isinstance(msg, dict) and msg.get("kind") == "PROGRESS" and msg.get("src") != "step":
                _hit()
                msg = dict(msg, src="step")
            return orig(self, w, msg, body)

        Coordinator._dispatch = dispatch
    elif MODE in ("shutdown-unbounded", "shutdown-any"):
        import inspect

        from wantrain.fault_tolerance.liveness import LivenessJudge

        init = LivenessJudge.__init__
        sig = inspect.signature(init)

        def judge_init(self, *args, **kwargs):
            bound = sig.bind(self, *args, **kwargs)
            bound.apply_defaults()
            if MODE == "shutdown-unbounded":
                if "shutdown_limit_s" in bound.arguments:
                    _hit()
                    bound.arguments["shutdown_limit_s"] = float("inf")
            else:
                self._wf_final = bound.arguments.get("final_step")
            init(*bound.args, **bound.kwargs)

        LivenessJudge.__init__ = judge_init
        if MODE == "shutdown-any":
            judge = LivenessJudge.judge

            def any_judge(self, states, now=None):
                final = getattr(self, "_wf_final", None)
                launched = [st for st in states if st.launched]
                added = []
                if final is not None and any(st.exit_code == 0 or st.last_step() == final for st in launched):
                    t = max((t for st in launched for (_s, t) in st.progress), default=0.0)
                    for st in launched:
                        if st.exit_code != 0 and st.last_step() != final:
                            st.progress.append((final, t))
                            added.append(st)
                if added:
                    _hit()
                try:
                    return judge(self, states, now)
                finally:
                    for st in added:
                        st.progress.pop()

            LivenessJudge.judge = any_judge
    elif MODE == "median-mean":
        from wantrain.runtime import telemetry

        orig = telemetry._median

        def mean(xs):
            xs = list(xs)
            if not xs:
                return orig(xs)
            _hit()
            return sum(xs) / len(xs)

        telemetry._median = mean
    elif MODE == "union-sum":
        from wantrain.runtime import telemetry

        orig = telemetry._union_len

        def total(intervals):
            intervals = list(intervals)
            _hit()
            return sum(b - a for a, b in intervals)

        telemetry._union_len = total
    else:
        raise RuntimeError("unknown WF_MUTANT " + MODE)
